// Hand-authored novel command: Excel report export. Not generated; safe
// across regeneration (no "Generated by" header).
package cli

import (
	"fmt"
	"strings"

	"github.com/spf13/cobra"
)

func newReportCmd(flags *rootFlags) *cobra.Command {
	var outputFile string
	var filter string
	var claim string
	var limit int

	cmd := &cobra.Command{
		Use:   "report <query>",
		Short: "Export an analyzed works report for a topic as an Excel (.xlsx) file",
		Long: "Fetch the most relevant works for a topic, classify each study's design and\n" +
			"stance (the same engine the consensus and evidence commands use), and write a\n" +
			"two-sheet Excel workbook: Works (one row per study with design, stance, and\n" +
			"citation data) and Summary (query metadata and stance/design aggregates).\n" +
			"Unlike 'export' (raw JSONL/JSON API dumps), 'report' writes analyzed,\n" +
			"spreadsheet-ready results.",
		Example: "  scientific-consensus-pp-cli report \"vitamin D respiratory infections\" --output report.xlsx\n" +
			"  scientific-consensus-pp-cli report \"microplastics\" -o mp.xlsx --claim \"microplastics harm human health\" --limit 100",
		Annotations: map[string]string{"pp:no-error-path-probe": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 && cmd.Flags().NFlag() == 0 {
				return cmd.Help()
			}
			query, err := requireQuery(args)
			if err != nil {
				return err
			}
			if outputFile == "" {
				return usageErr(fmt.Errorf("--output is required (path of the .xlsx file to write)"))
			}
			if !strings.HasSuffix(strings.ToLower(outputFile), ".xlsx") {
				return usageErr(fmt.Errorf("--output must end in .xlsx, got %q", outputFile))
			}
			if limit <= 0 {
				return usageErr(fmt.Errorf("--limit must be positive, got %d", limit))
			}
			if dryRunOK(flags) {
				fmt.Fprintf(cmd.OutOrStdout(), "would export an Excel report for %q to %s\n", query, outputFile)
				return nil
			}
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			ctx, cancel := boundCtx(cmd.Context(), flags)
			defer cancel()

			data, err := buildReportData(ctx, c, query, filter, claim, limit)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			if err := writeReportXLSX(outputFile, data); err != nil {
				return err
			}
			if flags.asJSON || flags.agent {
				return flags.printJSON(cmd, map[string]any{
					"file":          outputFile,
					"works":         data.Analyzed,
					"total_matches": data.TotalMatches,
					"supporting":    data.Supporting,
					"refuting":      data.Refuting,
					"mixed":         data.Mixed,
					"inconclusive":  data.Inconclusive,
					"apex_design":   data.ApexDesign,
					"stance_method": data.StanceMethod,
				})
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Exported %d works (of %d matches) to %s\n", data.Analyzed, data.TotalMatches, outputFile)
			if data.Analyzed == 0 {
				fmt.Fprintln(cmd.OutOrStdout(), "No works matched; the file contains headers and the Summary sheet only.")
			}
			return nil
		},
	}

	cmd.Flags().StringVarP(&outputFile, "output", "o", "", "Output .xlsx file path (required)")
	cmd.Flags().StringVar(&filter, "filter", "", "OpenAlex filter expression (e.g. from_publication_date:2020-01-01)")
	cmd.Flags().StringVar(&claim, "claim", "", "Claim to classify stance against (defaults to the query)")
	cmd.Flags().IntVar(&limit, "limit", 50, "Maximum works to analyze and export (max 200)")

	return cmd
}
